ENV_NAME = "env.json"                     # 1.3.0: el archivo antiguo (dentro de .dlpy_internal); ahora solo se lee para migrar
CONFIG_NAME = "dlpy_config.json"          # 1.3.0: la configuración vive en dlpy_files, fuera de .dlpy_internal (1.6.5: con DLPY_HIDE_FILES=1 es «.dlpy_config.json»)
