def lang_parse(raw, fallback=None):
    """1.7.0: "en", "en-US", "en_US", "English", "português" → código (es/en/pt/fr/de/it); None si no se reconoce."""
    if raw is None:
        return fallback
    s = str(raw).strip().lower().replace("_", "-")
    if not s or s in ("auto", "automatic", "automático", "automatico"):
        return fallback
    if s in LANG_ALIASES:
        return LANG_ALIASES[s]
    base = s.split("-")[0]
    if base in LANG_ALIASES:
        return LANG_ALIASES[base]
    return fallback


def lang_ask_pending(env=None):
    """1.7.1: True si DLPY_LANG vale «ask» o no está (el predeterminado): hay que preguntar el idioma en la escena. «auto» (el del sistema) o un código no preguntan."""
    v = str((os.environ if env is None else env).get("DLPY_LANG") or "").strip().lower()
    return v in ("", LANG_ASK, "preguntar", "?")


def _lang_detect():
    if lang_ask_pending():
        return DEFAULT_LANG          # 1.7.1: sin idioma elegido todo sale en inglés hasta que la escena pregunte (el LANG del sistema solo cuenta con DLPY_LANG=auto)
    for key in ("DLPY_LANG", "LANG", "LANGUAGE"):
        v = os.environ.get(key)
        if v:
            c = lang_parse(v)
            if c:
                return c
    return DEFAULT_LANG


LANG = _lang_detect()


