def languages_payload(current=None):
    """`--idiomas`: todos los idiomas disponibles para que Atajos arme la lista de elegir.
    «lang_labels» es lo que se ve (bandera + nombre, sin código y SIN el idioma actual); «lang_map» es el diccionario etiqueta → código
    (Atajos busca ahí lo que se eligió) y «lang_codes» va en paralelo a «lang_labels»; «lang_command» es el comando que guarda la elección
    (--config DLPY_LANG=código). «lang_current» / «lang_current_name» / «lang_title» dicen cuál está activo."""
    cur = current or LANG or DEFAULT_LANG
    langs = [{"code": c, "flag": LANG_FLAGS.get(c, ""), "name": LANG_NAMES.get(c, c), "english": LANG_ENGLISH.get(c, c),
              "label": ("%s %s" % (LANG_FLAGS.get(c, ""), LANG_NAMES.get(c, c))).strip(), "current": False,
              "set_text": LANG_SET_TEXT.get(c, LANG_SET_TEXT["en"])} for c in LANG_CODES if c != cur]
    return {"version": VERSION, "lang_current": cur, "lang_current_name": LANG_NAMES.get(cur, cur), "lang_default": DEFAULT_LANG,
            "lang_count": len(langs), "lang_ask": LANG_ASK, "lang_title": "%s: %s" % (LANG_CURRENT_TEXT.get(cur, LANG_CURRENT_TEXT["en"]), LANG_NAMES.get(cur, cur)),
            "lang_labels": [l["label"] for l in langs], "lang_codes": [l["code"] for l in langs],
            "lang_map": {l["label"]: l["code"] for l in langs}, "lang_list": langs,
            "lang_command": "--config DLPY_LANG=<code>",
            "lang_set": LANG_SET_TEXT.get(cur, LANG_SET_TEXT["en"]),                      # «Idioma establecido» en el idioma activo
            "lang_set_map": dict(LANG_SET_TEXT),                                         # código → «Idioma establecido» en ESE idioma: la alerta busca ahí el LangCode elegido
            "lang_set_texts": [LANG_SET_TEXT.get(c, LANG_SET_TEXT["en"]) for c in (l["code"] for l in langs)]}   # paralelo a lang_codes


def print_languages():
    """`python dlpy.py --idiomas` (alias `--langs`): una línea de JSON ASCII en la salida y nada más (sin banner ni animaciones)."""
    sys.stdout.write(json.dumps(languages_payload(), ensure_ascii=True, separators=(",", ":")) + "\n")
    sys.stdout.flush()
    return 0


def wants_languages(args):
    """¿Se pidió --idiomas / --langs? Acepta rayas largas («—idiomas»)."""
    return _wants(args, "idiomas") or _wants(args, "langs")


def set_lang(raw):
    """1.7.0: cambia el idioma en esta ejecución y lo deja en DLPY_LANG (lo guarda la configuración)."""
    global LANG
    code = lang_parse(raw) or DEFAULT_LANG
    LANG = code
    os.environ["DLPY_LANG"] = code
    return code



