_TPL_RX = []


def _t_rows(text, code):
    """1.7.3: traduce una frase con huecos (_TPL_ROWS). None si no encaja o el idioma no tiene filas. Los valores ({0}…) pasan tal cual."""
    if code not in _TPL_LANGS or not text:
        return None
    if not _TPL_RX:
        for es, tr in _TPL_ROWS:
            parts = re.split(r"\{(\d)\}", es)
            rx = "".join(re.escape(x) if i % 2 == 0 else "(.+?)" for i, x in enumerate(parts))
            _TPL_RX.append((re.compile("^" + rx + "$", re.S), tr, [int(x) for x in parts[1::2]]))
    core = text.rstrip(".")
    suf = text[len(core):]
    for rx, tr, order in _TPL_RX:
        m = rx.match(core)
        if not m:
            continue
        vals = {n: v for n, v in zip(order, m.groups())}
        out = tr[_TPL_LANGS.index(code)].format(*[vals[i] for i in range(max(vals) + 1)] if vals else ())
        if suf == "." and code in ("zh", "ja"):
            return out + "。"
        return out + suf
    return None


def _t_dotted(text, code):
    """1.7.3: «Frase del catálogo.» (con punto final) cuando el catálogo la tiene sin punto."""
    if text.endswith(".") and not text.endswith(".."):
        hit = (I18N.get(code) or {}).get(text[:-1])
        if hit is not None:
            return hit + ("。" if code in ("zh", "ja") else ".")
    return None



def _t_template(text, code):
    """Frases completas con variables («Actualización de pip: 1 → 2», «Se usará la 1.7.0 la próxima vez…»): None si no encaja."""
    tpl = I18N_FMT.get(code)
    if not tpl:
        return None
    for name, rx in _FMT_RX:
        m = rx.match(text)
        if not m or name not in tpl:
            continue
        g = list(m.groups())
        if name == "conv" and g[1]:
            inner = re.match(r"^ \((.*)\)$", g[1])
            g[1] = (" (" + " · ".join(t_display(x, lang=code) for x in inner.group(1).split(" · ")) + ")") if inner else g[1]
        if name == "reenc" and g[1] == "equipo":
            g[1] = I18N_DEVICE.get(code, g[1])
        return tpl[name].format(*g)
    return None


_LETTER = r"[^\W\d_]"          # una letra (no dígito ni _): las claves pueden pegarse a números («45s»), nunca a palabras
_SUB_RX = {}


def _sub_word(text, key, val):
    """Reemplaza `key` solo si no está dentro de una palabra («Espera» no toca «Esperando»)."""
    rx = _SUB_RX.get(key)
    if rx is None:
        pre = "(?<!%s)" % _LETTER if key[:1].isalpha() else ""
        post = "(?!%s)" % _LETTER if key[-1:].isalpha() else ""
        rx = _SUB_RX[key] = re.compile(pre + re.escape(key) + post)
    return rx.sub(lambda m: val, text)


_UNIT_RX = {}


def _sub_units(text, cat):
    """«2 horas», «3 días»: claves cortas que solo se traducen tras un número."""
    for k in ("horas", "hora", "días", "día"):
        v = cat.get(k)
        if not v or v == k:
            continue
        rx = _UNIT_RX.get(k)
        if rx is None:
            rx = _UNIT_RX[k] = re.compile(r"(?<=\d )" + re.escape(k) + "(?!%s)" % _LETTER)
        text = rx.sub(lambda m, v=v: v, text)
    return text


def _sub_phrase(text, code):
    """Frases sueltas (con audio, guardado…), con o sin mayúscula inicial y sin partir palabras."""
    for k, v in (I18N_PHRASES.get(code) or {}).items():
        key = k.strip()
        rx = _SUB_RX.get("ph:" + key)
        if rx is None:
            rx = _SUB_RX["ph:" + key] = re.compile("(?<!%s)" % _LETTER + re.escape(key) + "(?!%s)" % _LETTER, re.IGNORECASE)
        val = v.strip()
        text = rx.sub(lambda m, val=val: (val[:1].upper() + val[1:]) if m.group(0)[:1].isupper() else val, text)
    return text


def _t_segment(text, code):
    cat = I18N.get(code) or {}
    if text in cat:
        return cat[text]
    for k in sorted(cat, key=len, reverse=True):
        if text.startswith(k + " ") or text.startswith(k + " ·") or text.startswith(k + ":") or text.startswith(k + " ("):
            return cat[k] + text[len(k):]
    return None


def t_display(text, lang=None):
    """1.7.0: traduce `text` (español canónico) al idioma activo. Exacto, plantillas de frase completa, segmentos " · ",
    prefijo y subcadenas del catálogo (siempre por palabras enteras); si no hay traducción, tal cual."""
    if text is None:
        return text
    if not isinstance(text, str):
        text = str(text)
    code = lang or LANG
    if code == "es" or not text:
        return text
    if text.startswith("★ "):
        return "★ " + t_display(text[2:], lang=code)  # 1.7.0: la estrella no es texto
    cat = I18N.get(code) or {}
    if text in cat:
        return cat[text]
    full = _t_template(text, code)
    if full is not None:
        return full
    full = _t_rows(text, code)           # 1.7.3: frases con huecos (valores intercalados) en todos los idiomas
    if full is None:
        full = _t_dotted(text, code)     # 1.7.3: «…no cierres la app.» con el punto que el catálogo no trae
    if full is not None:
        return full
    # segmentos " · ": se traduce cada parte que tenga clave; el resto (versiones, nombres) se deja
    if " · " in text:
        parts = text.split(" · ")
        done = []
        any_hit = False
        for p in parts:
            d = _t_segment(p, code)
            if d is not None:
                done.append(d)
                any_hit = True
            else:
                done.append(p)
        out = " · ".join(done) if any_hit else text
    else:
        hit = _t_segment(text, code)
        out = hit if hit is not None else text
    # subcadenas del catálogo (claves largas) para frases con números/fechas intercalados
    if out == text or any(ch.isdigit() for ch in out):
        for k in sorted(cat, key=len, reverse=True):
            if len(k) < 6:
                continue
            if k in out and cat[k] != k:
                out = _sub_word(out, k, cat[k])
        out = _sub_units(out, cat)
    # frases dentro del texto (con audio, guardadas…)
    out = _sub_phrase(out, code)
    return out



def t(text, lang=None):
    return t_display(text, lang)


# ─────────────────────── [UX4b] Texto de las animaciones: un solo motor (1.7.1) ───────────────────────
# El dibujo (puntos, vías, chips, barras) es neutro; cualquier texto que lleve dentro sale de aquí, del idioma activo: se traduce primero y se mide después por su ancho
# real. Quien dibuja nunca compara ni mide texto en español. Las claves son el español canónico de siempre (catálogos I18N, I18N_WELCOME, I18N_UX).
CHIP_COLS = 8                       # 1.7.1: columnas de texto que caben en un chip (antes 6 caracteres)
_UX_CHIP_CACHE = {}


def ux_pick(*cands, room=None, fallback=None):
    """1.7.1: (índice, texto) del primer candidato (del más largo al más corto, en español canónico) que, YA TRADUCIDO, cabe en `room` columnas reales. Sin `room` toma el
    primero. Si ninguno cabe: `fallback` traducido (índice = len(cands)) o, sin él, el último recortado con «…»."""
    outs = [t_display(c) for c in cands]
    if room is None:
        return 0, outs[0]
    for i, s in enumerate(outs):
        if dwidth(s) <= room:
            return i, s
    if fallback is not None:
        return len(outs), t_display(fallback)
    return len(outs) - 1, fit_text(outs[-1], room)


def ux_text(*cands, room=None, fallback=None):
    """1.7.1: lo mismo que ux_pick pero solo el texto."""
    return ux_pick(*cands, room=room, fallback=fallback)[1]


def ux_chip(x, cols=None):
    """1.7.1: texto de un chip: en el idioma activo, en mayúsculas, solo caracteres que se ven y como mucho `cols` (CHIP_COLS) columnas reales («webm» → «WEBM», VIEJO → «OLD»)."""
    key = (LANG, str(x), cols)
    hit = _UX_CHIP_CACHE.get(key)
    if hit is not None:
        return hit
    s = t_display(" ".join(str(x or "").split())).upper()
    if s.startswith("DOLBY"):
        s = "DV"
    s = "".join(ch for ch in s if ch.isprintable() and dwidth(ch) >= 1)
    out = clip_text(s, cols or CHIP_COLS).strip()
    if len(_UX_CHIP_CACHE) > 512:
        _UX_CHIP_CACHE.clear()
    _UX_CHIP_CACHE[key] = out
    return out


def ux_enter_key(lang=None):
    """1.7.1: cómo se llama la tecla Enter en el idioma activo (Enter · Entrée · Invio)."""
    return UX_ENTER.get(lang or LANG, "Enter")


def ux_enter_names():
    """1.7.1: todos los nombres que puede tener la tecla Enter en una línea de opciones (para resaltarla en cualquier idioma)."""
    return set(UX_ENTER.values()) | {"Enter"}


CONFIG_KEY_RE = re.compile(r"^DLPY_[A-Z0-9_]+$")


def config_key(raw):
    """1.3.0: «rows» / «dlpy_rows» / «DLPY_ROWS» → «DLPY_ROWS»; None si no es un nombre válido."""
    k = str(raw or "").strip().upper().replace("-", "_")
    if not k.startswith("DLPY_"):
        k = "DLPY_" + k
    k = ENV_RENAMED.get(k, k)                                         # 1.7.1: --config FASTCONVERT=… llega al nombre nuevo
    return k if CONFIG_KEY_RE.match(k) else None


def config_write(data, path=None):
    """1.3.0: guarda `data` (solo DLPY_* de texto) en el archivo de configuración, de forma atómica. Crea la carpeta si falta."""
    path = path or ENV_FILE
    save_json(path, {k: v for k, v in data.items() if isinstance(k, str) and isinstance(v, str) and k.startswith("DLPY_") and k not in ENV_SKIP},
              mkdir=True, sort_keys=True)


def config_edit(items, path=None):
    """1.3.0:"""
    path = path or ENV_FILE
    data = _read_env_json(path)
    changes, errors = [], []
    for raw in items:
        name, eq, val = str(raw).partition("=")
        key = config_key(name)
        if key is None:
            errors.append(f"«{raw}»: nombre no válido (usa NOMBRE=valor)")
            continue
        if not eq:
            errors.append(f"«{raw}»: falta «=» (NOMBRE=valor guarda · NOMBRE= borra)")
            continue
        if key in ENV_SKIP:
            errors.append(f"{key}: es de una sola ejecución y no se guarda (usa export)")
            continue
        old, val = data.get(key), val.strip()
        if val:
            data[key] = val
        else:
            data.pop(key, None)
        new = val or None
        if old != new:
            changes.append((key, old, new))
    if changes:
        config_write(data, path)
    return changes, errors


